import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const container = new THREE.Group();

  // Aspect ratio of atlas region (512 × 320)
  const PLANE_WIDTH = 1.6;
  const PLANE_HEIGHT = 1.0;

  // Create plane geometry for textured sprite
  const geometry = new THREE.PlaneGeometry(PLANE_WIDTH, PLANE_HEIGHT);

  // Load ceramic grain texture
  const textureUrl = config.assetUrl || config.assets?.imageUrl;
  const textureMap = ctx.textureLoader.load(textureUrl);
  textureMap.colorSpace = THREE.SRGBColorSpace;

  // Create material using TSL texture node
  const textureNode = texture(textureMap);
  const material = new THREE.MeshBasicNodeMaterial({
    map: textureNode,
    side: THREE.DoubleSide
  });

  // Add textured plane to container
  const plane = new THREE.Mesh(geometry, material);
  container.add(plane);

  // Add text overlay if provided
  if (config.textContent && config.textContent.length > 0) {
    const textSpec = config.textContent[0];
    const textMesh = ctx.fontAtlas.createText(textSpec.text, {
      fontSize: textSpec.fontSize || 39,
      fontFamily: 'Lora',
      fontWeight: textSpec.fontWeight || 400,
      color: '#16161d'
    });

    if (textMesh) {
      textMesh.position.z = 0.01; // Layer above texture
      container.add(textMesh);
    }
  }

  // Apply scene placement
  const { position = {}, rotation = {}, scale = {} } = config;
  container.position.set(position.x ?? 0, position.y ?? 0, position.z ?? 0);
  container.rotation.set(rotation.x ?? 0, rotation.y ?? 0, rotation.z ?? 0);
  container.scale.set(scale.x ?? 1, scale.y ?? 1, scale.z ?? 1);

  // Apply cinematic primitives
  const primitives = config.cinematicPrimitives || [];
  primitives.forEach(({ name, params }) => {
    if (ctx.primitives?.[name]) {
      ctx.primitives[name](container, params || {});
    }
  });

  // Cleanup function
  container.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureMap.dispose();
    gsap.killTweensOf(container);
    gsap.killTweensOf(plane);
  };

  return container;
}
